<?php require_once __DIR__.'/../config/config.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$id=(int)(admin_user()['id']??0);if(!$id){$error='Your admin session has expired. Sign in again.';}elseif($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid name and email.';else{if($pass!==''){$q=$pdo->prepare('UPDATE users SET name=?,email=?,password_hash=? WHERE id=?');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$id]);}else{$q=$pdo->prepare('UPDATE users SET name=?,email=? WHERE id=?');$q->execute([$name,$email,$id]);}$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;flash('notice','Admin account updated.');header('Location: account.php');exit;}}$pageTitle='Admin account';$active='account';require __DIR__.'/_layout.php';?><section class="welcome-row"><div><p class="eyebrow">ACCOUNT SECURITY</p><h1>Keep your access <em>secure.</em></h1><p class="muted">Update the name, email and password for the current administrator.</p></div></section><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><section class="panel form-panel narrow"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label class="span-2">Display name<input name="name" required value="<?=e($admin['name']??'')?>"></label><label class="span-2">Email address<input type="email" name="email" required value="<?=e($admin['email']??'')?>"></label><label class="span-2">New password <small>(leave blank to keep current)</small><input type="password" name="password" minlength="12" autocomplete="new-password"></label><div class="span-2"><button class="btn btn-primary">Update account ↗</button></div></form></section><?php require __DIR__.'/_footer.php';?>
